<?php require __DIR__.'/../includes/bootstrap.php';if(!academy_ready())redirect('academy/index.php');$course=academy_by_slug(trim($_GET['slug']??''));if(!$course||($course['status']!=='approved'&&!can_manage_course($course))){http_response_code(404);exit('Course not found.');}$u=user();
if($_SERVER['REQUEST_METHOD']==='POST'){require_auth();verify_csrf();$action=$_POST['action']??'';if($action==='enroll'){academy_enroll((int)$course['id'],(int)user()['id'],(int)($course['capacity']??0));flash('success','Enrollment updated.');}elseif($action==='complete_lesson'){academy_complete_lesson((int)$_POST['lesson_id'],(int)$course['id'],(int)user()['id']);flash('success','Lesson marked complete.');}redirect_route('academy/view.php',['slug'=>$course['slug']]);}
$lessons=academy_lessons((int)$course['id']);$instructors=academy_instructors((int)$course['id']);$enrollment=$u?academy_enrollment((int)$course['id'],(int)$u['id']):null;$completed=$u?academy_completed_lesson_ids((int)$course['id'],(int)$u['id']):[];
app_header($course['title']);?><section class="course-hero"><?php if($course['banner_path']):?><img src="<?=e(base_url($course['banner_path']))?>" alt=""><?php endif?><div><p class="eyebrow"><?=e(strtoupper(str_replace('_',' ',$course['category'])))?></p><h1><?=e($course['title'])?></h1><p class="lead"><?=e($course['subtitle'])?></p><div class="pill-row"><span class="pill"><?=e(academy_levels()[$course['level']]??$course['level'])?></span><span class="pill"><?=e(academy_formats()[$course['format']]??$course['format'])?></span><span class="pill"><?=count($lessons)?> lessons</span></div><p><strong><?=$course['price']>0?'$'.number_format((float)$course['price'],2):'Free'?></strong></p><?php if($u&&!can_manage_course($course)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="enroll"><button class="button primary"><?=$enrollment?'Enrollment: '.ucwords(str_replace('_',' ',$enrollment['status'])):'Enroll Now'?></button></form><?php elseif(!$u):?><a class="button primary" href="../login.php">Sign in to Enroll</a><?php endif?></div></section><div class="two-column-layout"><section><article class="app-card"><h2>About This Course</h2><p><?=nl2br(e($course['description']))?></p></article><article class="app-card"><h2>Course Lessons</h2><?php foreach($lessons as $i=>$lesson):$locked=!$enrollment&&!$lesson['is_preview']&&!can_manage_course($course);?><article class="lesson-row"><div><p class="eyebrow">LESSON <?=$i+1?> · <?=e(strtoupper(str_replace('_',' ',$lesson['lesson_type'])))?></p><h3><?=e($lesson['title'])?></h3><p><?=e($lesson['summary'])?></p><?php if(!$locked&&$lesson['content']):?><div class="lesson-content"><?=nl2br(e($lesson['content']))?></div><?php elseif($locked):?><p class="muted">Enroll to unlock this lesson.</p><?php endif?></div><?php if($enrollment&&!in_array((int)$lesson['id'],$completed,true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="complete_lesson"><input type="hidden" name="lesson_id" value="<?=(int)$lesson['id']?>"><button class="button ghost small">Mark Complete</button></form><?php elseif(in_array((int)$lesson['id'],$completed,true)):?><span class="badge">Completed</span><?php endif?></article><?php endforeach?><?php if(!$lessons):?><p class="muted">Lessons are being prepared.</p><?php endif?></article></section><aside><article class="app-card"><h2>Instructor<?=count($instructors)===1?'':'s'?></h2><?php foreach($instructors as $inst):?><p><strong><?=e($inst['display_name'])?></strong><br><?=e(ucfirst($inst['role']))?></p><?php endforeach?></article><?php if(can_manage_course($course)):?><a class="button primary full-width" href="manage.php?id=<?=(int)$course['id']?>">Manage Course</a><?php endif?></aside></div><?php app_footer();
